class EmbedMorseSmaleSegmentation(Node):
    def __init__(self, parent_node_id : str):
        super().__init__(parent_node_id, types.MorseSmaleSegmentation, types.MorseSmaleSegmentationEmbedding, locals(), partial_cache = True)

    @classmethod
    def chat_description(cls):
        return "queued embedding morse smale segmentation"

    @classmethod
    def description(cls):
        return 'Computes a geometric embedding of a Morse-Smale complex.'

    @classmethod
    def param_descriptions(cls):
        return {'parent_node_id': 'A node of type morse_smale_complex that we are embedding.'}

    def compatible_to_visualize(self, other):
        if issubclass(other.node_type, SquareOrCubeEmbedding):
            return False, f"Cannot embed a node of type {self.node_type.get_mcp_name()} along with another "\
                          f"of type {other.node_type.get_mcp_name()}. They will overlap in the visualization"

        return True, ""

    def _evaluation_logic(self, parent_data, time_step):
        ms_values = set()

        vtk_vti = servermanager.Fetch(parent_data.msc)
        numPoints = vtk_vti.GetNumberOfPoints()
        vtk_array = vtk_vti.GetPointData().GetArray("Scalars__MorseSmaleManifold")

        for i in range(numPoints):
            ms_values.add(vtk_array.GetTuple1(i))

        ms_values = list(ms_values)
        ms_values.sort()

        lut = random_categorical_lut(ms_values, "morse-smale-segmentation-colors")

        return types.MorseSmaleSegmentationEmbedding(parent_data.msc, lut, vtk_vti.GetDimensions())

    def _evaluation_logic_partial_cache(self, parent_data, partial_cache, time_step):
        partial_cache.msc = parent_data.msc
        return partial_cache

