class PersistenceSimplification(Node):
    def __init__(self, parent_node_id : str, epsilon : float):
        super().__init__(parent_node_id, Scalar, Scalar, locals())

        self.epsilon = epsilon

    @classmethod
    def guardrails(cls):
        return [piecewise_linear_guardrail]

    @classmethod
    def chat_description(cls):
        return "queued applying persistence simplification"

    @classmethod
    def description(cls):
        return 'Applies persistence simplification to a scalar field with a given persistence threshold' \
               'epsilon. This is based on the piecewise-linear topology.'

    @classmethod
    def param_descriptions(cls):
        return {'parent_node_id': 'The id of a node of type scalar corresponding to the scalar field '
                           'for which persistence simplification is taken.',
         'epsilon': 'The persistence threshold to apply for simplification. This is expressed as a fraction of the function range '
                    'where 0 means no simplification and 1 means simplify by the entire function range.'}

    @classmethod
    def mandatory_parameters(cls):
        return ["epsilon"]

    def _evaluation_logic(self, parent_data, time_step):

        ts = ttk.TTKTopologicalSimplificationByPersistence(Input=parent_data.data)
        ts.InputArray = ['POINTS', 'Scalars_']
        ts.PersistenceThreshold = self.epsilon

        return Scalar(ts)

